VERSION='UAM_50M_CREDIT_DIAG_1H_20261102_V1'
PROJECT=Path(__file__).resolve().parent
sys.dont_write_bytecode=True


def digest(path):
    value=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(1024*1024),b''):value.update(block)
    return value.hexdigest()


def read(path):return json.loads(Path(path).read_text(encoding='utf-8-sig'))


def clean(value):
    if isinstance(value,dict):return {str(k):clean(v) for k,v in value.items()}
    if isinstance(value,(list,tuple)):return [clean(v) for v in value]
    if hasattr(value,'tolist'):return clean(value.tolist())
    if isinstance(value,float) and not math.isfinite(value):return None
    return value


def save(path,value):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    temporary=path.with_name(path.name+f'.pending_{os.getpid()}')
    temporary.write_text(json.dumps(clean(value),ensure_ascii=False,indent=2,allow_nan=False),encoding='utf-8')
    os.replace(temporary,path)


def module(name,blob,wanted):
    raw=zlib.decompress(base64.b85decode(blob))
    if hashlib.sha256(raw).hexdigest()!=wanted:raise RuntimeError('封存代码hash不符')
    tree=ast.parse(raw.decode('utf-8-sig'))
    tree.body=[n for n in tree.body if not (isinstance(n,ast.If) and isinstance(n.test,ast.Compare) and isinstance(n.test.left,ast.Name) and n.test.left.id=='__name__')]
    result=types.ModuleType(name);result.__file__=str(Path(__file__).resolve());sys.modules[name]=result
    exec(compile(tree,'<'+name+'>','exec'),result.__dict__)
    return result


def cases(source):
    plan=read(source/'SUITE_PLAN.json');tasks=plan['tasks']
    if plan.get('script_sha256')!=FROZEN_50M_SHA:raise RuntimeError('输入不是已封存的50M训练合同')
    chosen=[]
    # 不依成绩挑模型；每种条件保留四个种子，先跑主线两端及普通Transformer，再补单因子。
    for arm in ('L00','L11_BOTH','T11_BOTH','L10_TIME','L01_BATCH'):
        for seed in (1701,1702,1703,1704):
            for control in ('J3','LQ'):
                matches=[t for t in tasks if t['k']==3 and t['seed']==seed and t['control']==control and t['arm']==arm]
                if len(matches)!=1:raise RuntimeError('50M模型登记缺失或不唯一')
                t=matches[0]
                if not t['id'].replace('_','').isalnum() or t.get('environment')!='E1' or t.get('fleet')!=12 or t.get('reward_mode')!='PT_POST':
                    raise RuntimeError('任务标识或物理/奖励合同异常')
                d=source/'cells'/t['id'];pointer=d/'checkpoints/step_001003520.json'
                if not pointer.is_file():raise RuntimeError('最终模型指针缺失：'+t['id'])
                cp=read(pointer);paths=[pointer.parent/Path(cp[k]).name for k in ('model','vecnorm')]
                if any(not p.is_file() or p.is_symlink() or not p.resolve().is_relative_to(source) for p in paths):
                    raise RuntimeError('模型配套缺失或路径重定向：'+t['id'])
                chosen.append(dict(case=t['id'],family='pt',controller='MODEL',training_seed=seed,k=3,label=control+'_'+arm,
                    task=t,model_id=t['id'],model=str(paths[0]),norm=str(paths[1]),
                    model_sha=digest(paths[0]),norm_sha=digest(paths[1]),old_supplement=False))
    # 强规则只保留一个真实控制器，不能按训练种子复制成多个独立样本。
    ready=dict(chosen[1]);ready.update(case='READY_K3',controller='READY',training_seed=None,label='强规则K3')
    return [ready]+chosen


def runtime(job):
    d=module('frozen_hour_tools',FROZEN_DIAG_B85,FROZEN_DIAG_SHA)
    payload=d.bundle();base=types.ModuleType('frozen_clone_tools');base.__file__=str(Path(__file__).resolve());sys.modules[base.__name__]=base
    exec(compile(payload['diagnostic_base'],'<frozen_clone_tools>','exec'),base.__dict__)
    m=module('frozen_gap50_runtime',FROZEN_50M_B85,FROZEN_50M_SHA)
    work=Path(job['work']);work.mkdir(parents=True,exist_ok=True)
    os.environ.update(UAM_STRICT_MODE='E1',UAM_STRICT_FLEET='12',UAM_STRICT_LOG_EVENTS='0',
                      MPLCONFIGDIR=str(work/'cache'),XDG_CACHE_HOME=str(work/'cache'))
    private=dict(id=job['case']['model_id'],family='pt',task=job['case']['task'],root=str(work/'environment'),out=str(work),run_root=job['run_root'])
    m.gap_setup(job['case']['task'],Path(private['root']),'eval')
    from loguru import logger
    logger.remove();m.torch.set_num_threads(1)
    c=job['case']
    if digest(c['model'])!=c['model_sha'] or digest(c['norm'])!=c['norm_sha']:raise RuntimeError('模型输入hash改变')
    model=m.FullPPO.load(c['model'],device='cpu')
    class NormLoader(pickle.Unpickler):
        def find_class(self,mod,name):
            if mod in ('__main__','__mp_main__') and hasattr(m,name):return getattr(m,name)
            return super().find_class(mod,name)
    with Path(c['norm']).open('rb') as stream:norm=NormLoader(stream).load()
    norm.training=False;norm.norm_reward=False;model.policy.set_training_mode(False)
    for p in model.policy.parameters():p.requires_grad_(False)
    def forbidden(*unused,**kw):raise RuntimeError('本轮无训练，禁止优化器更新')
    model.learn=model.train=forbidden
    if getattr(model.policy,'optimizer',None) is not None:model.policy.optimizer.step=forbidden
    if next(model.policy.parameters()).device.type!='cpu':raise RuntimeError('诊断不得分配GPU')
    d.check=lambda unused:check(job)
    base.check_pause=lambda unused:check(job)
    d.branch=discount_branch
    d.pair_list=lambda tape,seed,maximum=24:original_pairs(d,tape,seed,12)
    d.sample_indices=lambda seed,trace:sample_indices(seed,trace)
    return d,base,m,model,norm,private


def check(job):
    if (Path(job['run_root'])/'STOP_REQUESTED').exists() or time.monotonic()>=job['deadline']:
        raise TimeoutError('本轮时间预算结束或收到停止请求；已完成单元保留')


def sample_indices(seed,trace):
    rng=random.Random(20261102+seed+sum(map(ord,trace)));selected=[]
    for start in (0,100,200):selected+=rng.sample(list(range(start,start+100)),2)
    return sorted(selected),sorted(selected)


def original_pairs(d,tape,seed,maximum):
    # 固定各站总人数，且不交换最后60位；不根据好坏挑交换位置。
    pairs=[(i,j) for i in range(min(240,len(tape))) for j in range(i+1,min(240,len(tape))) if tape[i]!=tape[j]]
    random.Random(seed).shuffle(pairs);return pairs[:maximum]


def discount_branch(base,m,job,private,template,obs,model,norm,action,horizon,scope,continuation,mode):
    """一遍物理回放同时记两个折扣和三个窗口；折扣仅用于离线标签，不改仿真。"""
    check(job);env=base.clone_env(template);current=obs.copy()
    initial=set(env.scenario.persons.persons);focal=env.scenario.waiting_decisions[0] if env.scenario.waiting_decisions else None
    if scope=='COMMITTED':base.hide_future(env)
    elif scope!='REALIZED':raise RuntimeError('信息边界未知')
    totals=[0,0,0];discounted=0.;post_discounted=0.;post_total=0.;after_cut=0.;snapshots={};ticks=0
    initial_rng=(random.getstate(),m.np.random.get_state(),m.torch.get_rng_state().clone())
    actual_mode=mode if continuation=='BASE' else 'READY'
    try:
        with m.torch.no_grad():
            for offset in range(horizon):
                check(job);s=env.scenario;unfinished=set(s.persons.persons)-set(s.finished_ids)
                totals[0]+=int(focal in unfinished);totals[1]+=len((unfinished & initial)-{focal});totals[2]+=len(unfinished-initial)
                discounted+=(.99**offset)*len(unfinished)
                if s.time>=500:after_cut+=len(unfinished)
                current,done,_,_=base.advance(m,private,env,current,model,norm,mode if offset==0 else actual_mode,action if offset==0 else None)
                post_count=len(set(s.persons.persons)-set(s.finished_ids))
                post_total+=post_count;post_discounted+=(.99**offset)*post_count
                ticks+=1
                if ticks in (60,120,240) or ticks==horizon or done:
                    snapshots[str(ticks)]=dict(total=sum(totals),focal=totals[0],existing=totals[1],future=totals[2],
                        discounted_099=discounted,discounted_100=sum(totals),after_train_cutoff500=after_cut,
                        reward_post_g099=post_discounted,reward_post_g100=post_total,
                        finished=len(set(s.finished_ids)),observed_ticks=ticks)
                if done:break
        for h in (60,120,240):
            if h<=horizon and str(h) not in snapshots:snapshots[str(h)]=dict(snapshots[str(ticks)],clipped=True)
        # 计数接口沿用旧脚本，只写本轮派生记录。
        counters=job['_counters'];counters['candidate_calls']=counters.get('candidate_calls',0)+1
        counters['completed_simulated_minutes']=counters.get('completed_simulated_minutes',0)+ticks
        result=dict(snapshots=snapshots,ticks=ticks)
        if scope=='REALIZED':
            # 同一状态、同一随机背景另算“没有新请求”的近似；只作为离线标签可靠性检查。
            random.setstate(initial_rng[0]);m.np.random.set_state(initial_rng[1]);m.torch.set_rng_state(initial_rng[2])
            known=discount_branch(base,m,job,private,template,obs,model,norm,action,horizon,'COMMITTED',continuation,mode)
            result['committed_snapshots']=known['snapshots']
        return result
    finally:env.close()


def worker(path):
    job=read(path);check(job);d,base,m,model,norm,private=runtime(job)
    job['_counters']=dict(started_monotonic=time.monotonic(),started_at=time.time(),full_episodes=0,candidate_calls=0,completed_simulated_minutes=0)
    job['_counter_path']=str(Path(job['out'])/'COUNTERS.json')
    initial_sha=m.policy_sha(model.policy)
    try:
        for bank in job['bank']:
            check(job);here=Path(job['run_root'])/'cases'/job['case']['case']/bank['name']
            path=here/'BASE.json'
            initial=read(path) if path.exists() else d.episode(base,m,job,private,model,norm,bank,capture=True)
            if not path.exists():save(path,initial)
            # 在相同源确认bank上复现50M最终指标；不要求新顺序冒充原验证结果。
            if job['case']['controller']=='MODEL':
                old=read(Path(job['source'])/'cells'/job['case']['model_id']/'evaluation/step_001003520.json')
                matches=[e for e in old['episodes'] if e['trace']==bank['name'] and e['eval_seed']==123]
                if len(matches)!=1 or abs(matches[0]['restricted_person_time_per_generated']-initial['metrics']['restricted_person_time_per_generated'])>1e-7:
                    raise RuntimeError('最终原模型配套复现不一致，拒绝后续标签')
            if job['phase']=='B_系统可行改善':
                anchor=d.repair_tail(base,m,job,private,model,norm,bank,'BASE',initial,job['case']['controller'])
                d.search_swaps(base,m,job,private,model,norm,bank,anchor)
            else:
                # 本轮只保留主线三臂和强规则的分支，开关臂已有完整回放对照。
                d.cache_episode=lambda *a,**kw:initial
                d.branches_for_case(base,m,job,private,model,norm,bank,False)
        if m.policy_sha(model.policy)!=initial_sha:raise RuntimeError('冻结策略权重被改变')
        save(Path(job['out'])/'END.json',dict(status='COMPLETE',weights_unchanged=True,new_training_transitions=0))
    finally:save(job['_counter_path'],job['_counters'])


def summarize(out,items):
    rows=[];rank=[]
    for c in items:
        for bank in ('original','order_4301','order_4302'):
            here=out/'cases'/c['case']/bank;p=here/'BASE.json'
            if not p.exists():continue
            e=read(p)['metrics'];r=dict(case=c['case'],control=c['task']['control'],arm=c['task']['arm'],seed=c['training_seed'],trace=bank,
                controller=c['controller'],rpt=e['restricted_person_time_per_generated'],completion=e['completion'],full=e['full'],att=e['ATT'])
            if (here/'TAIL_BASE.json').exists():
                t=read(here/'TAIL_BASE.json')['best']['metrics'];r.update(tail_rpt=t['restricted_person_time_per_generated'],tail_full=t['full'])
            if (here/'SWAPS.json').exists():
                s=read(here/'SWAPS.json');r.update(swap_rpt=s['best']['metrics']['restricted_person_time_per_generated'],swap_trials=len(s['trials']))
            rows.append(r)
            for path in (here/'C_BRANCHES').glob('state_*.json'):
                x=read(path)
                for follow in sorted({v['continuation'] for v in x['rows']}):
                    candidates=[v for v in x['rows'] if v['continuation']==follow and v['scope']=='REALIZED']
                    for horizon in (60,120,240):
                        costs=[v['snapshots'][str(horizon)] for v in candidates]
                        best=lambda name:{i for i,v in enumerate(costs) if abs(v[name]-min(t[name] for t in costs))<1e-8}
                        original=x['original_reference']
                        ref_index=next(i for i,v in enumerate(candidates) if v['action']==original)
                        winner=min(range(len(costs)),key=lambda i:(costs[i]['total'],i!=ref_index,i))
                        known_costs=[v['committed_snapshots'][str(horizon)]['total'] for v in candidates]
                        known_best={i for i,v in enumerate(known_costs) if v==min(known_costs)}
                        known_pick=min(known_best,key=lambda i:(i!=ref_index,i))
                        ref,win=costs[ref_index],costs[winner]
                        rank.append(dict(case=c['case'],trace=bank,index=x['index'],time=x['time'],continuation=follow,horizon=horizon,
                            candidates=len(costs),discount_optima_disjoint=not bool(best('discounted_099') & best('total')),
                            post_discount_optima_disjoint=not bool(best('reward_post_g099') & best('reward_post_g100')),
                            pre_post_g100_optima_disjoint=not bool(best('total') & best('reward_post_g100')),
                            committed_realized_optima_disjoint=not bool(known_best & best('total')),
                            committed_picked_realized_gain=ref['total']-costs[known_pick]['total'],
                            local_oracle_gain=ref['total']-win['total'],focal_gain=ref['focal']-win['focal'],
                            existing_gain=ref['existing']-win['existing'],future_gain=ref['future']-win['future'],
                            max_after_train_cutoff500=max(v['after_train_cutoff500'] for v in costs),
                            offline_only=True))
    def output(name,data):
        if not data:return
        fields=list(dict.fromkeys(k for r in data for k in r))
        with (out/name).open('w',encoding='utf-8-sig',newline='') as stream:
            w=csv.DictWriter(stream,fieldnames=fields);w.writeheader();w.writerows(data)
    output('01_逐模型完整尾批交换.csv',rows);output('02_折扣窗口排序.csv',rank)
    save(out/'TRAINING_ADVICE.json',dict(automatic_training=False,
        advice='先比较同等尾批后的普通Transformer与强READY；折扣排序变化只是归因线索，不能直接宣称gamma是唯一原因',
        if_no_headroom='不启用新的WM/MARL，现有18h代码只作普通基线和目标范围校准',
        if_headroom='四种子复现后才研究候选值修正；真实未来只用于离线诊断，不进入策略输入'))


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--source',type=Path,default=PROJECT/'serial_runs/uam_gap_factors_48run_50m_v1')
    ap.add_argument('--out',type=Path,default=PROJECT/'workspace/artifacts/uam_50m_credit_diag_1h_20261102_v1')
    ap.add_argument('--wall-seconds',type=int,default=3600);ap.add_argument('--workers',type=int,default=2)
    ap.add_argument('--resume',action='store_true');ap.add_argument('--retry-failed',action='store_true');ap.add_argument('--worker')
    ap.add_argument('--plan',action='store_true');args=ap.parse_args()
    if args.worker:
        try:worker(args.worker)
        except TimeoutError:raise SystemExit(130)
        return
    if args.plan:
        print(json.dumps(dict(version=VERSION,cases=41,full_replays=123,swaps_per_case_trace=12,
            branch_cases=25,states_per_case_trace=6,wall_seconds=args.wall_seconds,new_training_transitions=0),ensure_ascii=False,indent=2));return
    if args.source.is_symlink() or args.out.is_symlink():raise RuntimeError('输入输出最终路径不能为符号链接')
    source,out=args.source.resolve(),args.out.resolve()
    if source.name!='uam_gap_factors_48run_50m_v1' or not source.is_relative_to(PROJECT/'serial_runs'):raise RuntimeError('输入必须是本项目明确的50M目录')
    if out.parent!=(PROJECT/'workspace/artifacts').resolve() or not out.name.startswith('uam_50m_credit_diag_'):
        raise RuntimeError('输出只能是workspace/artifacts下本轮专属前缀的一层目录')
    if args.wall_seconds<60 or args.wall_seconds>3600 or args.workers not in (1,2):raise RuntimeError('时间最多一小时、CPU worker最多2')
    if out.exists() and not args.resume:raise RuntimeError('已有诊断目录；使用--resume或换新名字')
    out.mkdir(parents=True,exist_ok=True)
    d=module('frozen_hour_parent',FROZEN_DIAG_B85,FROZEN_DIAG_SHA)
    d.PROJECT=PROJECT
    d.resource_check(out)
    lock=(out/'PARENT.lock').open('a+b')
    if os.name!='nt':
        import fcntl
        fcntl.flock(lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    else:
        import msvcrt
        lock.seek(0)
        if not lock.read(1):lock.write(b'0');lock.flush()
        lock.seek(0);msvcrt.locking(lock.fileno(),msvcrt.LK_NBLCK,1)
    items=cases(source);plan=read(source/'SUITE_PLAN.json')
    bank=[x for x in plan['config']['bank'] if x['name'] in ('original','order_4301','order_4302')]
    for item in bank:
        p=Path(item['path'])
        # 可从原服务器路径直接读取；项目迁移时按文件名映射到当前源目录。
        if not p.is_file():p=source/'bank'/p.name
        if not p.is_file() and item['name']=='original':
            found=list((source/'_author_source').glob('*/train_data/passengers_300.csv'))
            if len(found)==1:p=found[0]
        if not p.is_file() or not p.resolve().is_relative_to(source) or digest(p)!=item['sha256']:raise RuntimeError('需求文件缺失或hash不符')
        item['path']=str(p.resolve())
    contract=dict(version=VERSION,script_sha256=digest(__file__),source=str(source),cases=items,bank=bank,workers=args.workers,
        no_training=True,windows=[60,120,240],swap_proposals=12,states_per_case_trace=6)
    prior=out/'MANIFEST.json'
    if prior.exists() and read(prior)!=contract:raise RuntimeError('续跑合同改变，不混用旧记录')
    if not prior.exists():save(prior,contract)
    started=time.monotonic();deadline=started+args.wall_seconds-20
    results=[]
    try:
        for phase,fraction in [('B_系统可行改善',.55),('C_决策过程归因',1.)]:
            phase_end=min(deadline,started+args.wall_seconds*fraction)
            selected=items if phase.startswith('B') else [c for c in items if c['controller']=='READY' or c['task']['arm'] in ('L00','L11_BOTH','T11_BOTH')]
            jobs=[]
            for c in selected:
                folder=out/'jobs'/phase/c['case'];folder.mkdir(parents=True,exist_ok=True)
                jobs.append(dict(case=c,phase=phase,run_root=str(out),source=str(source),source_root=str(source),
                    out=str(folder),work=str(out/'work'/c['case']),deadline=phase_end,bank=bank))
            with ThreadPoolExecutor(max_workers=args.workers) as pool:
                futures={pool.submit(d.launch,j,args.retry_failed):j for j in jobs}
                for f in as_completed(futures):
                    try:result=f.result()
                    except Exception as error:result=dict(status='FAILED',error=str(error))
                    results.append(result);save(out/'progress.json',dict(phase=phase,completed=len(results),new_training_transitions=0,last=result))
                    print('[诊断单元]',result,flush=True)
        summarize(out,items)
        complete=all((out/'jobs'/'B_系统可行改善'/c['case']/'END.json').exists() for c in items)
        branch_items=[c for c in items if c['controller']=='READY' or c['task']['arm'] in ('L00','L11_BOTH','T11_BOTH')]
        complete=complete and all((out/'jobs'/'C_决策过程归因'/c['case']/'END.json').exists() for c in branch_items)
        unchanged=all(digest(c['model'])==c['model_sha'] and digest(c['norm'])==c['norm_sha'] for c in items)
        if not unchanged:raise RuntimeError('输入权重改变，不能发布完成结论')
        save(out/'SESSION_END.json',dict(status='COMPLETE' if complete else 'BUDGET_PARTIAL',wall_seconds=time.monotonic()-started,
            weights_unchanged=unchanged,new_training_transitions=0,results=results))
        archive=out/(out.name+'_DATAONLY.tar.gz');temp=archive.with_suffix('.pending')
        with tarfile.open(temp,'w:gz') as tar:
            for p in out.rglob('*'):
                if p.is_file() and not p.is_symlink() and 'work' not in p.relative_to(out).parts and p.suffix in ('.json','.csv','.log','.md'):
                    tar.add(p,arcname=out.name+'/'+p.relative_to(out).as_posix(),recursive=False)
            tar.add(Path(__file__).resolve(),arcname=out.name+'/ENTRYPOINT.py',recursive=False)
        os.replace(temp,archive);print('[数据包]',archive,flush=True)
    finally:lock.close()


if __name__=='__main__':main()
